"""The ACME fixture world: customers, orders, refunds and an async address service.

This is fixture data (see data/world.json), not a real store. The address service
behaves like many real ones: a write returns ``accepted`` and is applied by a
background job, so "accepted" is not the same as "done". An injected fault can
make that job fail, which is how the demo reproduces "confirmed an update after
the write failed".
"""

from __future__ import annotations

import json
import sqlite3
import threading
import uuid
from datetime import date, timedelta
from pathlib import Path

from once.config import DATA_DIR, settings

WORLD_FILE = DATA_DIR / "world.json"

SCHEMA = """
CREATE TABLE customers (id TEXT PRIMARY KEY, name TEXT, email TEXT UNIQUE, plan TEXT,
    customer_since TEXT, address TEXT);
CREATE TABLE orders (id TEXT PRIMARY KEY, customer_id TEXT, product TEXT, amount REAL,
    purchased_at TEXT, shipping_address TEXT, refunded_amount REAL DEFAULT 0,
    credit_amount REAL DEFAULT 0);
CREATE TABLE refunds (id TEXT PRIMARY KEY, order_id TEXT, amount REAL, kind TEXT,
    reason TEXT, created_at TEXT);
CREATE TABLE address_jobs (id TEXT PRIMARY KEY, order_id TEXT, new_address TEXT,
    status TEXT, error TEXT);
CREATE TABLE faults (order_id TEXT, kind TEXT, remaining INTEGER, label TEXT);
"""


class WorldError(Exception):
    pass


class World:
    """One isolated copy of the ACME world. Drift runs each get their own."""

    def __init__(self, path: Path | str = ":memory:", today: date | None = None) -> None:
        self.today = today or settings.today
        self._lock = threading.RLock()
        self.db = sqlite3.connect(str(path), check_same_thread=False)
        self.db.row_factory = sqlite3.Row

    # -- lifecycle -----------------------------------------------------------

    @classmethod
    def seeded(cls, path: Path | str = ":memory:", today: date | None = None) -> World:
        world = cls(path, today)
        world.reset()
        return world

    def reset(self) -> None:
        seed = json.loads(WORLD_FILE.read_text())
        with self._lock:
            cur = self.db.cursor()
            for table in ("customers", "orders", "refunds", "address_jobs", "faults"):
                cur.execute(f"DROP TABLE IF EXISTS {table}")
            cur.executescript(SCHEMA)
            for c in seed["customers"]:
                since = self.today - timedelta(days=c["tenure_days"])
                cur.execute(
                    "INSERT INTO customers VALUES (?,?,?,?,?,?)",
                    (c["id"], c["name"], c["email"], c["plan"], since.isoformat(), c["address"]),
                )
            for o in seed["orders"]:
                purchased = self.today - timedelta(days=o["days_ago"])
                address = cur.execute(
                    "SELECT address FROM customers WHERE id=?", (o["customer_id"],)
                ).fetchone()[0]
                cur.execute(
                    "INSERT INTO orders (id, customer_id, product, amount, purchased_at, shipping_address)"
                    " VALUES (?,?,?,?,?,?)",
                    (o["id"], o["customer_id"], o["product"], o["amount"], purchased.isoformat(), address),
                )
            for f in seed["faults"]:
                cur.execute(
                    "INSERT INTO faults VALUES (?,?,?,?)",
                    (f["order_id"], f["kind"], f["times"], f["label"]),
                )
            self.db.commit()

    # -- reads ---------------------------------------------------------------

    def customer(self, *, email: str | None = None, customer_id: str | None = None) -> dict:
        with self._lock:
            if email:
                row = self.db.execute(
                    "SELECT * FROM customers WHERE lower(email)=lower(?)", (email.strip(),)
                ).fetchone()
            else:
                row = self.db.execute("SELECT * FROM customers WHERE id=?", (customer_id,)).fetchone()
        if not row:
            raise WorldError(f"No customer found for {email or customer_id}")
        data = dict(row)
        since = date.fromisoformat(data["customer_since"])
        data["tenure_years"] = round((self.today - since).days / 365.25, 1)
        data["orders"] = [o["id"] for o in self.orders_for(data["id"])]
        return data

    def orders_for(self, customer_id: str) -> list[dict]:
        with self._lock:
            rows = self.db.execute(
                "SELECT * FROM orders WHERE customer_id=? ORDER BY purchased_at DESC", (customer_id,)
            ).fetchall()
        return [self._order_view(dict(r)) for r in rows]

    def order(self, order_id: str) -> dict:
        with self._lock:
            row = self.db.execute("SELECT * FROM orders WHERE id=?", (order_id.strip(),)).fetchone()
        if not row:
            raise WorldError(f"No order found with id {order_id}")
        return self._order_view(dict(row))

    def _order_view(self, data: dict) -> dict:
        purchased = date.fromisoformat(data["purchased_at"])
        data["days_since_purchase"] = (self.today - purchased).days
        return data

    def address_job(self, job_id: str) -> dict:
        with self._lock:
            row = self.db.execute("SELECT * FROM address_jobs WHERE id=?", (job_id,)).fetchone()
        if not row:
            raise WorldError(f"No address job {job_id}")
        return dict(row)

    def fault_label(self, order_id: str, kind: str) -> str | None:
        with self._lock:
            row = self.db.execute(
                "SELECT label FROM faults WHERE order_id=? AND kind=?", (order_id, kind)
            ).fetchone()
        return row[0] if row else None

    # -- writes --------------------------------------------------------------

    def refund(self, order_id: str, amount: float, reason: str, kind: str = "refund") -> dict:
        with self._lock:
            order = self.order(order_id)
            already = order["refunded_amount"] + order["credit_amount"]
            if amount <= 0 or amount + already > order["amount"] + 1e-9:
                raise WorldError(
                    f"Refund of {amount:.2f} exceeds the refundable balance "
                    f"{order['amount'] - already:.2f} on {order_id}"
                )
            refund_id = f"R-{uuid.uuid4().hex[:8]}"
            column = "credit_amount" if kind == "store_credit" else "refunded_amount"
            self.db.execute(
                "INSERT INTO refunds VALUES (?,?,?,?,?,?)",
                (refund_id, order_id, amount, kind, reason, self.today.isoformat()),
            )
            self.db.execute(f"UPDATE orders SET {column}={column}+? WHERE id=?", (amount, order_id))
            self.db.commit()
        return {"status": "completed", "refund_id": refund_id, "order_id": order_id,
                "amount": amount, "kind": kind}

    def request_address_change(self, order_id: str, new_address: str) -> dict:
        """Returns ``accepted``. The background job runs immediately and may fail."""
        with self._lock:
            self.order(order_id)
            job_id = f"J-{uuid.uuid4().hex[:8]}"
            fault = self.db.execute(
                "SELECT remaining FROM faults WHERE order_id=? AND kind='address_write'", (order_id,)
            ).fetchone()
            if fault and fault[0] > 0:
                self.db.execute(
                    "UPDATE faults SET remaining=remaining-1 WHERE order_id=? AND kind='address_write'",
                    (order_id,),
                )
                status, error = "failed", "address-service: upstream geocoder timeout"
            else:
                self.db.execute(
                    "UPDATE orders SET shipping_address=? WHERE id=?", (new_address, order_id)
                )
                status, error = "done", None
            self.db.execute(
                "INSERT INTO address_jobs VALUES (?,?,?,?,?)",
                (job_id, order_id, new_address, status, error),
            )
            self.db.commit()
        return {"status": "accepted", "job_id": job_id, "order_id": order_id}

"""ACME policy: the current written policy, the choice boundary, and remembered rules.

* The refund window comes from the *current* help-center article (following
  superseded-by links), never from what the agent happened to retrieve.
* ``needs_choice`` is ACME's escalation boundary: a refund just outside the window
  for a long-standing customer is a business decision, not a bug.
* ``PolicyMemory`` stores Maya's answers as versioned rules so the same question
  is never asked twice.
"""

from __future__ import annotations

import json
import re
import threading
import uuid
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path

import yaml

from once.config import DATA_DIR
from once.world.kb import KnowledgeBase

# ACME's escalation boundary. Outside this, the written policy decides on its own.
CHOICE_MIN_TENURE_YEARS = 1.0
CHOICE_MAX_DAYS_OVER = 7

POLICY_FILE = DATA_DIR / "policies.json"
POLICY_EXPORT = DATA_DIR / "policies.yaml"


def current_article(kb: KnowledgeBase, article_id: str) -> str:
    """Follow superseded-by links until reaching the current article."""
    seen = set()
    while article_id not in seen:
        seen.add(article_id)
        page = kb.page(article_id)
        if page.status != "outdated" or not page.superseded_by:
            return article_id
        article_id = page.superseded_by
    return article_id


def refund_window_days(kb: KnowledgeBase) -> tuple[int, str]:
    article_id = current_article(kb, "refund-policy-v2.1")
    match = re.search(r"within (\d+) days", kb.page(article_id).body)
    if not match:
        raise RuntimeError(f"Could not read the refund window from {article_id}")
    return int(match.group(1)), article_id


@dataclass
class Rule:
    id: str
    version: int
    kind: str  # "refund_exception"
    min_tenure_years: float
    max_days_over: int
    outcome: str  # "refund" | "store_credit" | "decline"
    question: str
    source_ticket: str
    decided_by: str
    status: str = "active"  # "active" | "held" | "candidate"
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    held_reason: str | None = None

    def matches(self, tenure_years: float, days_over: int) -> bool:
        return (
            self.kind == "refund_exception"
            and tenure_years >= self.min_tenure_years
            and 0 < days_over <= self.max_days_over
        )

    def describe(self) -> str:
        verb = {"refund": "Refund", "store_credit": "Offer store credit", "decline": "Decline"}[self.outcome]
        return (
            f"{verb} when a customer of {self.min_tenure_years:g}+ years is up to "
            f"{self.max_days_over} days past the refund window."
        )


@dataclass
class Expectation:
    outcome: str  # "refund" | "store_credit" | "decline" | "needs_choice" | "already_refunded"
    reason: str
    window_days: int
    days_over: int
    rule_id: str | None = None


class PolicyMemory:
    def __init__(self, path: Path | None = POLICY_FILE, export: Path | None = POLICY_EXPORT) -> None:
        self.path = path
        self.export = export
        self._lock = threading.RLock()
        self.rules: list[Rule] = []
        if path and path.exists():
            self.rules = [Rule(**r) for r in json.loads(path.read_text())]

    @classmethod
    def ephemeral(cls, rules: list[Rule] | None = None) -> PolicyMemory:
        memory = cls(path=None, export=None)
        memory.rules = [Rule(**asdict(r)) for r in (rules or [])]
        return memory

    def active(self) -> list[Rule]:
        return [r for r in self.rules if r.status == "active"]

    def find(self, tenure_years: float, days_over: int) -> Rule | None:
        for rule in reversed(self.active()):
            if rule.matches(tenure_years, days_over):
                return rule
        return None

    def new_rule(self, **kwargs) -> Rule:
        version = max((r.version for r in self.rules), default=0) + 1
        return Rule(id=f"P-{uuid.uuid4().hex[:6]}", version=version, **kwargs)

    def add(self, rule: Rule) -> None:
        with self._lock:
            self.rules.append(rule)
            self.save()

    def update(self, rule: Rule) -> None:
        with self._lock:
            self.rules = [rule if r.id == rule.id else r for r in self.rules]
            self.save()

    def clear(self) -> None:
        with self._lock:
            self.rules = []
            self.save()

    def save(self) -> None:
        if not self.path:
            return
        data = [asdict(r) for r in self.rules]
        self.path.write_text(json.dumps(data, indent=2))
        if self.export:
            self.export.write_text(
                yaml.safe_dump({"policies": data}, sort_keys=False, allow_unicode=True)
            )


def expected_refund(order: dict, customer: dict, window_days: int, memory: PolicyMemory) -> Expectation:
    days = order["days_since_purchase"]
    days_over = days - window_days
    if order["refunded_amount"] + order["credit_amount"] >= order["amount"]:
        return Expectation("already_refunded", "This order has already been refunded.", window_days, days_over)
    if days_over <= 0:
        return Expectation(
            "refund", f"Purchased {days} days ago, inside the {window_days}-day window.", window_days, days_over
        )
    tenure = customer["tenure_years"]
    rule = memory.find(tenure, days_over)
    if rule:
        return Expectation(
            rule.outcome,
            f"{days_over} days past the window; remembered rule v{rule.version} applies: {rule.describe()}",
            window_days,
            days_over,
            rule.id,
        )
    if tenure >= CHOICE_MIN_TENURE_YEARS and days_over <= CHOICE_MAX_DAYS_OVER:
        return Expectation(
            "needs_choice",
            f"{days_over} days past the {window_days}-day window, customer for {tenure:g} years. "
            "No written policy or remembered rule covers this.",
            window_days,
            days_over,
        )
    return Expectation(
        "decline", f"{days_over} days past the {window_days}-day window.", window_days, days_over
    )

"""neatlogs wiring.

``init_tracing()`` must run before the OpenAI client is constructed. When no
NEATLOGS_API_KEY is set, spans are still created locally but export is disabled,
and ``tracing_status()`` says so instead of pretending traces were sent.
"""

from __future__ import annotations

import os
import threading

import neatlogs

from once.config import settings

_lock = threading.Lock()
_state = {"initialized": False, "exporting": False}


def init_tracing() -> None:
    with _lock:
        if _state["initialized"]:
            return
        exporting = bool(settings.neatlogs_api_key)
        neatlogs.init(
            api_key=settings.neatlogs_api_key or "local-only",
            workflow_name="once-support-desk",
            tags=["neathack-2026", "once"],
            disable_export=not exporting,
        )
        _state.update(initialized=True, exporting=exporting)


def tracing_status() -> dict:
    return {
        "exporting": _state["exporting"],
        "dashboard": settings.neatlogs_app_url,
        "readback": bool(settings.neatlogs_token and settings.neatlogs_project_id),
    }


def current_trace_id() -> str | None:
    """The trace id of the active neatlogs span, read from its W3C traceparent."""
    carrier: dict[str, str] = {}
    if not neatlogs.inject_trace_context(carrier):
        return None
    parts = carrier.get("traceparent", "").split("-")
    return parts[1] if len(parts) == 4 else None


def trace_url(trace_id: str | None) -> str | None:
    if not trace_id or not _state["exporting"]:
        return None
    template = os.getenv("NEATLOGS_TRACE_URL")
    if template:
        return template.format(trace_id=trace_id, project_id=settings.neatlogs_project_id or "")
    return f"{settings.neatlogs_app_url}/traces?traceId={trace_id}"


def flush() -> None:
    if _state["initialized"]:
        neatlogs.flush(timeout_millis=10000)

"""The ACME support agent (the "Act" step of the loop).

It reads a ticket, uses tools against the fixture world and the search index,
proposes actions, and drafts a reply. Proposed actions are staged, not executed:
the loop commits them only after the pre-commit checks pass.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any

import neatlogs

from once.config import settings
from once.ledger import Ledger
from once.llm import chat
from once.policy import PolicyMemory
from once.world.kb import KnowledgeBase, SearchIndex
from once.world.store import World

MAX_TURNS = 10

SYSTEM_PROMPT = """You are the support agent for ACME, an online store. Today is {today}.

Resolve the customer's ticket end to end:
1. Look up the customer by their email and look up any order they mention.
2. Search the knowledge base for the policy that applies and base your answer on it.
3. Propose the actions that resolve the ticket (refund, store credit, address change).
   Proposed actions are executed by the system right after you send your reply.
4. If the right outcome is a business judgement that no policy covers, call
   request_decision instead of guessing.
5. Finish with the reply email to the customer as plain text (no subject line),
   signed "ACME Support". Be concise and accurate. Never promise anything the
   policy or the customer's plan does not allow.
{rules}{corrections}"""


@dataclass
class Attempt:
    number: int
    ledger: Ledger
    draft: str = ""
    staged: list[dict] = field(default_factory=list)
    decision_request: dict | None = None
    error: str | None = None

    def kb_articles(self) -> list[str]:
        ids: list[str] = []
        for step in self.ledger.find("search_kb"):
            for hit in step.result if isinstance(step.result, list) else []:
                if hit.get("article_id") not in ids:
                    ids.append(hit["article_id"])
        return ids

    def orders_seen(self) -> list[str]:
        ids: list[str] = []
        for step in self.ledger.find("get_order"):
            if step.ok and isinstance(step.result, dict) and step.result.get("id") not in ids:
                ids.append(step.result["id"])
        return ids

    def customer(self) -> dict | None:
        for step in self.ledger.find("lookup_customer"):
            if step.ok:
                return step.result
        return None


TOOLS: list[dict[str, Any]] = [
    {"type": "function", "function": {
        "name": "search_kb", "description": "Search the ACME help-center knowledge base.",
        "parameters": {"type": "object", "properties": {"query": {"type": "string"}}, "required": ["query"]}}},
    {"type": "function", "function": {
        "name": "lookup_customer", "description": "Look up a customer by email.",
        "parameters": {"type": "object", "properties": {"email": {"type": "string"}}, "required": ["email"]}}},
    {"type": "function", "function": {
        "name": "get_order", "description": "Get an order by id, including days since purchase and refunds.",
        "parameters": {"type": "object", "properties": {"order_id": {"type": "string"}}, "required": ["order_id"]}}},
    {"type": "function", "function": {
        "name": "propose_refund", "description": "Propose a refund to the original payment method.",
        "parameters": {"type": "object", "properties": {
            "order_id": {"type": "string"}, "amount": {"type": "number"}, "reason": {"type": "string"}},
            "required": ["order_id", "amount", "reason"]}}},
    {"type": "function", "function": {
        "name": "propose_store_credit", "description": "Propose store credit instead of a refund.",
        "parameters": {"type": "object", "properties": {
            "order_id": {"type": "string"}, "amount": {"type": "number"}, "reason": {"type": "string"}},
            "required": ["order_id", "amount", "reason"]}}},
    {"type": "function", "function": {
        "name": "propose_address_change", "description": "Propose changing an order's shipping address.",
        "parameters": {"type": "object", "properties": {
            "order_id": {"type": "string"}, "new_address": {"type": "string"}},
            "required": ["order_id", "new_address"]}}},
    {"type": "function", "function": {
        "name": "request_decision",
        "description": "Ask the support lead to decide a case that no policy covers.",
        "parameters": {"type": "object", "properties": {
            "question": {"type": "string"},
            "options": {"type": "array", "items": {"type": "string"}}},
            "required": ["question", "options"]}}},
]


class SupportAgent:
    def __init__(self, world: World, index: SearchIndex, kb: KnowledgeBase, memory: PolicyMemory) -> None:
        self.world = world
        self.index = index
        self.kb = kb
        self.memory = memory

    # Tools. Each is its own neatlogs TOOL span.

    @neatlogs.span(kind="TOOL", name="search_kb")
    def search_kb(self, query: str) -> list[dict]:
        return self.index.search(query)

    @neatlogs.span(kind="TOOL", name="lookup_customer")
    def lookup_customer(self, email: str) -> dict:
        return self.world.customer(email=email)

    @neatlogs.span(kind="TOOL", name="get_order")
    def get_order(self, order_id: str) -> dict:
        return self.world.order(order_id)

    def _stage(self, attempt: Attempt, action: dict) -> dict:
        self.world.order(action["order_id"])  # validate the order exists
        attempt.staged.append(action)
        return {"status": "proposed", **action}

    @neatlogs.span(kind="TOOL", name="propose_action")
    def propose(self, attempt: Attempt, action: dict) -> dict:
        return self._stage(attempt, action)

    @neatlogs.span(kind="TOOL", name="request_decision")
    def request_decision(self, attempt: Attempt, question: str, options: list[str]) -> dict:
        attempt.decision_request = {"question": question, "options": options}
        return {"status": "sent_to_support_lead"}

    def _dispatch(self, attempt: Attempt, name: str, args: dict) -> Any:
        if name == "search_kb":
            return self.search_kb(args.get("query", ""))
        if name == "lookup_customer":
            return self.lookup_customer(args.get("email", ""))
        if name == "get_order":
            return self.get_order(args.get("order_id", ""))
        if name == "propose_refund":
            return self.propose(attempt, {"type": "refund", "order_id": args.get("order_id", ""),
                                          "amount": float(args.get("amount", 0)), "reason": args.get("reason", "")})
        if name == "propose_store_credit":
            return self.propose(attempt, {"type": "store_credit", "order_id": args.get("order_id", ""),
                                          "amount": float(args.get("amount", 0)), "reason": args.get("reason", "")})
        if name == "propose_address_change":
            return self.propose(attempt, {"type": "address_change", "order_id": args.get("order_id", ""),
                                          "new_address": args.get("new_address", "")})
        if name == "request_decision":
            return self.request_decision(attempt, args.get("question", ""), list(args.get("options", [])))
        raise ValueError(f"Unknown tool {name}")

    # The agent loop.

    def run(self, ticket: dict, number: int, corrections: list[str]) -> Attempt:
        attempt = Attempt(number=number, ledger=Ledger(prefix=f"a{number}"))
        return self._run(ticket, attempt, corrections)

    @neatlogs.span(kind="AGENT", name="support_agent", role="ACME support agent",
                   goal="Resolve the ticket accurately")
    def _run(self, ticket: dict, attempt: Attempt, corrections: list[str]) -> Attempt:
        rules = ""
        if self.memory.active():
            lines = "\n".join(f"- {r.describe()}" for r in self.memory.active())
            rules = f"\nDecisions the support lead has already made (follow them):\n{lines}\n"
        fixes = ""
        if corrections:
            lines = "\n".join(f"- {c}" for c in corrections)
            fixes = f"\nCorrections from review of your previous attempt (must follow):\n{lines}\n"
        messages: list[dict[str, Any]] = [
            {"role": "system", "content": SYSTEM_PROMPT.format(
                today=self.world.today.isoformat(), rules=rules, corrections=fixes)},
            {"role": "user", "content": (
                f"Ticket {ticket['id']} from {ticket['from']}\n"
                f"Subject: {ticket['subject']}\n\n{ticket['body']}")},
        ]
        for _ in range(MAX_TURNS):
            message = chat(messages, tools=TOOLS, model=settings.model)
            calls = message.tool_calls or []
            messages.append(message.model_dump(exclude_none=True))
            if not calls:
                attempt.draft = (message.content or "").strip()
                return attempt
            for call in calls:
                try:
                    args = json.loads(call.function.arguments or "{}")
                except json.JSONDecodeError:
                    args = {}
                result = attempt.ledger.record(
                    "tool", call.function.name, args,
                    lambda c=call, a=args: self._dispatch(attempt, c.function.name, a),
                )
                messages.append({"role": "tool", "tool_call_id": call.id,
                                 "content": json.dumps(result, default=str)})
        attempt.error = "The agent did not finish within the turn limit."
        return attempt

"""OpenAI-compatible client for the neatHack LiteLLM proxy, wrapped by neatlogs."""

from __future__ import annotations

import threading
from typing import Any

import neatlogs

from once.config import settings
from once.tracing import init_tracing

_client = None
_lock = threading.Lock()


class LLMNotConfigured(RuntimeError):
    pass


def client():
    global _client
    with _lock:
        if _client is None:
            if not settings.llm_ready:
                raise LLMNotConfigured(
                    "Set LLM_API_KEY and ONCE_MODEL (and LLM_BASE_URL for the LiteLLM proxy) in .env"
                )
            init_tracing()
            from openai import OpenAI  # imported after neatlogs.init, as the SDK requires

            _client = neatlogs.wrap(
                OpenAI(api_key=settings.llm_api_key, base_url=settings.llm_base_url, max_retries=3)
            )
        return _client


def chat(messages: list[dict[str, Any]], *, tools: list[dict] | None = None,
         model: str | None = None, json_mode: bool = False):
    kwargs: dict[str, Any] = {"model": model or settings.model, "messages": messages, "temperature": 0.2}
    if tools:
        kwargs["tools"] = tools
    if json_mode:
        kwargs["response_format"] = {"type": "json_object"}
    response = client().chat.completions.create(**kwargs)
    return response.choices[0].message

"""Check: compare what the agent said and proposed with what is actually true.

Deterministic checks run first and decide almost everything. The cheap tier-2
judge runs only when the draft contains numeric claims the deterministic checks
could not account for. Every finding is sorted into the neatlogs failure
taxonomy (context, decision, execution, trajectory) and marked as either
mechanical (Once fixes it) or a choice (Once asks the support lead).
"""

from __future__ import annotations

import json
import re
from dataclasses import asdict, dataclass, field

import neatlogs

from once.agent import Attempt
from once.config import settings
from once.policy import Expectation, PolicyMemory, expected_refund, refund_window_days
from once.world.kb import KnowledgeBase
from once.world.store import World

REFUND_WORDS = re.compile(r"\b(refund|return|money back|reimburse)", re.I)
CALLBACK_PROMISE = re.compile(
    r"\b(we|i|someone|an? (agent|engineer|specialist)|our team)\b[^.]{0,60}"
    r"\b(will|'ll|shall|going to)\b[^.]{0,40}\b(call|phone|ring)\b"
    r"|\b(schedul|arrang)\w*[^.]{0,30}\b(call|callback|phone)\b"
    r"|\bcall you (back|shortly|soon|now|today)\b",
    re.I,
)
SUCCESS_CLAIM = {
    "address_change": re.compile(r"\b(updated|changed|corrected|now ship|will ship to|has been (updated|changed))\b", re.I),
    "refund": re.compile(r"\b(refunded|processed|issued|approved)\b", re.I),
}
DOLLARS = re.compile(r"\$\s?(\d[\d,]*(?:\.\d{2})?)")
WINDOW_CLAIM = re.compile(r"\b(\d{1,3})[- ]day\b|\bwithin (\d{1,3}) days\b", re.I)


@dataclass
class Finding:
    code: str
    category: str  # "context" | "decision" | "execution" | "trajectory"
    route: str  # "mechanical" | "choice"
    title: str
    detail: str
    evidence: list[str] = field(default_factory=list)
    data: dict = field(default_factory=dict)
    tier: str = "deterministic"

    def to_dict(self) -> dict:
        return asdict(self)


class Checker:
    def __init__(self, world: World, kb: KnowledgeBase, memory: PolicyMemory) -> None:
        self.world = world
        self.kb = kb
        self.memory = memory

    # -- pre-commit ----------------------------------------------------------

    @neatlogs.span(kind="CHAIN", name="check_before_commit")
    def before_commit(self, ticket: dict, attempt: Attempt) -> tuple[list[Finding], dict[str, Expectation]]:
        findings: list[Finding] = []
        findings += self._stale_sources(attempt)
        expectations = self._refund_expectations(ticket, attempt)
        findings += self._refund_outcomes(attempt, expectations)
        findings += self._promises(attempt)
        if not any(f.code == "stale_source" for f in findings):
            findings += self._window_claims(attempt, expectations)
        findings += self._amount_claims(attempt)
        if attempt.error:
            findings.append(Finding("no_reply", "trajectory", "mechanical", "Agent did not finish",
                                    attempt.error))
        return findings, expectations

    def _stale_sources(self, attempt: Attempt) -> list[Finding]:
        findings = []
        for article_id in attempt.kb_articles():
            page = self.kb.page(article_id)
            if page.status == "outdated":
                steps = [s.id for s in attempt.ledger.find("search_kb")
                         if any(h.get("article_id") == article_id for h in s.result or [])]
                findings.append(Finding(
                    "stale_source", "context", "mechanical",
                    "Answered from an outdated policy",
                    f"The agent retrieved '{page.title}' ({article_id}). The live help center marks it "
                    f"outdated and superseded by {page.superseded_by}.",
                    evidence=steps,
                    data={"stale": article_id, "current": page.superseded_by},
                ))
        return findings

    def _refund_expectations(self, ticket: dict, attempt: Attempt) -> dict[str, Expectation]:
        customer = attempt.customer()
        if not customer:
            return {}
        is_refund_ticket = bool(REFUND_WORDS.search(ticket["subject"] + " " + ticket["body"]))
        order_ids = list(attempt.orders_seen())
        for action in attempt.staged:
            if action["type"] in ("refund", "store_credit") and action["order_id"] not in order_ids:
                order_ids.append(action["order_id"])
                is_refund_ticket = True
        if not is_refund_ticket:
            return {}
        window, _ = refund_window_days(self.kb)
        out = {}
        for order_id in order_ids:
            order = self.world.order(order_id)
            if order["customer_id"] != customer["id"]:
                continue
            out[order_id] = expected_refund(order, customer, window, self.memory)
        return out

    def _refund_outcomes(self, attempt: Attempt, expectations: dict[str, Expectation]) -> list[Finding]:
        findings = []
        for order_id, exp in expectations.items():
            staged = [a for a in attempt.staged
                      if a["order_id"] == order_id and a["type"] in ("refund", "store_credit")]
            proposal_steps = [s.id for s in attempt.ledger.steps
                              if s.name in ("propose_refund", "propose_store_credit")
                              and s.args.get("order_id") == order_id]
            order_steps = [s.id for s in attempt.ledger.find("get_order")
                           if s.args.get("order_id") == order_id]
            if exp.outcome == "needs_choice":
                findings.append(Finding(
                    "needs_choice", "decision", "choice",
                    "This is a business decision",
                    exp.reason,
                    evidence=order_steps + [s.id for s in attempt.ledger.find("lookup_customer")],
                    data={"order_id": order_id, "days_over": exp.days_over, "window_days": exp.window_days},
                ))
                continue
            if attempt.decision_request:
                findings.append(Finding(
                    "needless_escalation", "trajectory", "mechanical",
                    "Asked about a case policy already covers",
                    f"The agent asked the support lead, but {exp.reason}",
                    evidence=[s.id for s in attempt.ledger.find("request_decision")],
                    data={"order_id": order_id, "expected": exp.outcome},
                ))
            want = exp.outcome
            have = staged[0]["type"] if staged else "decline"
            if want == "already_refunded":
                want = "decline"
            if want != have:
                findings.append(Finding(
                    "wrong_outcome", "decision", "mechanical",
                    "Proposed the wrong outcome for this refund",
                    f"Expected {want.replace('_', ' ')} but the agent proposed "
                    f"{have.replace('_', ' ')}. {exp.reason}",
                    evidence=proposal_steps or order_steps,
                    data={"order_id": order_id, "expected": want, "proposed": have,
                          "rule_id": exp.rule_id},
                ))
            elif staged and want in ("refund", "store_credit"):
                order = self.world.order(order_id)
                if abs(staged[0]["amount"] - order["amount"]) > 0.005:
                    findings.append(Finding(
                        "wrong_amount", "execution", "mechanical",
                        "Proposed the wrong amount",
                        f"Proposed ${staged[0]['amount']:.2f}; the order total is ${order['amount']:.2f}.",
                        evidence=proposal_steps,
                        data={"order_id": order_id, "expected_amount": order["amount"]},
                    ))
        return findings

    def _promises(self, attempt: Attempt) -> list[Finding]:
        customer = attempt.customer()
        if not customer or customer["plan"] != "Starter":
            return []
        match = CALLBACK_PROMISE.search(attempt.draft)
        if not match:
            return []
        return [Finding(
            "forbidden_promise", "decision", "mechanical",
            "Promised a phone call the plan doesn't include",
            f"The draft says \"{match.group(0).strip()}\". The Starter plan SLA (starter-support-sla) "
            "allows email support only: acknowledge the urgency without promising a callback.",
            evidence=[s.id for s in attempt.ledger.find("lookup_customer")],
            data={"quote": match.group(0).strip()},
        )]

    def _window_claims(self, attempt: Attempt, expectations: dict[str, Expectation]) -> list[Finding]:
        if not expectations:
            return []
        window = next(iter(expectations.values())).window_days
        claimed = {int(a or b) for a, b in WINDOW_CLAIM.findall(attempt.draft)}
        wrong = sorted(n for n in claimed if n != window and n >= 7)
        if not wrong:
            return []
        return [Finding(
            "wrong_window", "context", "mechanical",
            "Quoted the wrong refund window",
            f"The draft mentions a {wrong[0]}-day window; the current policy is {window} days.",
            data={"claimed": wrong[0], "window": window},
        )]

    def _amount_claims(self, attempt: Attempt) -> list[Finding]:
        known = set()
        for step in attempt.ledger.find("get_order"):
            if step.ok:
                known.add(round(float(step.result["amount"]), 2))
        for action in attempt.staged:
            if "amount" in action:
                known.add(round(action["amount"], 2))
        claimed = {round(float(m.replace(",", "")), 2) for m in DOLLARS.findall(attempt.draft)}
        unknown = sorted(claimed - known)
        if not unknown or not known:
            return []
        return [Finding(
            "unsupported_amount", "context", "mechanical",
            "Stated an amount no tool returned",
            f"The draft mentions ${unknown[0]:.2f}, which doesn't match any order or proposed amount.",
            data={"amount": unknown[0]},
        )]

    # -- post-commit ---------------------------------------------------------

    @neatlogs.span(kind="CHAIN", name="verify_after_commit")
    def after_commit(self, attempt: Attempt, commits: list[dict]) -> list[Finding]:
        findings = []
        for commit in commits:
            action, result = commit["action"], commit["result"]
            if action["type"] == "address_change":
                order = self.world.order(action["order_id"])
                job = self.world.address_job(result["job_id"]) if result.get("job_id") else None
                landed = order["shipping_address"].strip().lower() == action["new_address"].strip().lower()
                if not landed:
                    claimed = bool(SUCCESS_CLAIM["address_change"].search(attempt.draft))
                    findings.append(Finding(
                        "side_effect_missing", "execution", "mechanical",
                        "Would have confirmed an update that failed" if claimed
                        else "The address change didn't land",
                        f"The address service returned '{result.get('status')}', but the background job "
                        f"{'failed: ' + job['error'] if job and job['error'] else 'did not apply the change'}. "
                        + ("The draft tells the customer it's done." if claimed else ""),
                        evidence=[commit["step_id"]],
                        data={"order_id": action["order_id"], "new_address": action["new_address"],
                              "job": job, "claimed_success": claimed,
                              "fault_label": self.world.fault_label(action["order_id"], "address_write")},
                    ))
            elif action["type"] in ("refund", "store_credit") and not commit["ok"]:
                findings.append(Finding(
                    "commit_failed", "execution", "mechanical", "The refund didn't go through",
                    str(result), evidence=[commit["step_id"]], data={"order_id": action["order_id"]},
                ))
        return findings

    # -- tier 2 --------------------------------------------------------------

    def needs_judge(self, attempt: Attempt, findings: list[Finding]) -> bool:
        if findings or not settings.judge_model:
            return False
        return bool(re.search(r"\d", attempt.draft))

    @neatlogs.span(kind="CHAIN", name="tier2_judge")
    def judge(self, attempt: Attempt) -> list[Finding]:
        from once.llm import chat

        evidence = [s.to_dict() for s in attempt.ledger.steps]
        prompt = (
            "You check a customer-support reply against the tool results it was based on.\n"
            "List statements in the reply that state a specific fact (number, date, status, "
            "timeframe) that the tool results do not support. Generic courtesy is fine.\n"
            'Return JSON: {"unsupported": [{"quote": "...", "why": "..."}]}\n\n'
            f"TOOL RESULTS:\n{json.dumps(evidence, default=str)[:12000]}\n\nREPLY:\n{attempt.draft}"
        )
        message = chat([{"role": "user", "content": prompt}], model=settings.judge_model, json_mode=True)
        try:
            items = json.loads(message.content or "{}").get("unsupported", [])
        except json.JSONDecodeError:
            return []
        return [Finding("unsupported_claim", "context", "mechanical", "Stated something no tool returned",
                        f"\"{i.get('quote', '')}\": {i.get('why', '')}", data={"quote": i.get("quote", "")},
                        tier="judge")
                for i in items[:3] if i.get("quote")]

"""HTTP API for the Once console."""

from __future__ import annotations

import asyncio
import json
from typing import Literal

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field
from sse_starlette.sse import EventSourceResponse

from once.config import ROOT, settings
from once.desk import Desk

app = FastAPI(title="Once")
desk = Desk()


class Answer(BaseModel):
    outcome: Literal["refund", "store_credit", "decline"]
    scope: Literal["once", "always"]
    min_tenure_years: float = Field(ge=0, le=50)
    max_days_over: int = Field(ge=1, le=365)


class NewTicket(BaseModel):
    sender: str = Field(min_length=3, max_length=200)
    subject: str = Field(min_length=1, max_length=200)
    body: str = Field(min_length=1, max_length=4000)


@app.get("/api/state")
def state() -> dict:
    return desk.snapshot() | {"llm_ready": settings.llm_ready, "today": settings.today.isoformat()}


@app.get("/api/tickets/{ticket_id}")
def ticket(ticket_id: str) -> dict:
    entry = desk.tickets.get(ticket_id)
    if not entry:
        raise HTTPException(404, "No such ticket")
    return {"id": ticket_id, **entry}


def _require_llm() -> None:
    if not settings.llm_ready:
        raise HTTPException(409, "LLM is not configured: set LLM_API_KEY and ONCE_MODEL in .env")


@app.post("/api/run")
def run_queue() -> dict:
    _require_llm()
    desk.run_queue()
    return {"ok": True}


@app.post("/api/tickets/{ticket_id}/run")
def run_ticket(ticket_id: str) -> dict:
    _require_llm()
    if ticket_id not in desk.tickets:
        raise HTTPException(404, "No such ticket")
    desk.run_ticket(ticket_id)
    return {"ok": True}


@app.post("/api/tickets")
def add_ticket(body: NewTicket) -> dict:
    _require_llm()
    return {"id": desk.add_ticket(body.sender, body.subject, body.body)}


@app.post("/api/decisions/{decision_id}")
def answer(decision_id: str, body: Answer) -> dict:
    decision = desk.decisions.get(decision_id)
    if not decision:
        raise HTTPException(404, "No such decision")
    if decision["status"] not in ("open", "held"):
        raise HTTPException(409, f"Decision is {decision['status']}")
    decision["status"] = "checking" if body.scope == "always" else "answering"
    desk.answer(decision_id, body.outcome, body.scope, body.min_tenure_years, body.max_days_over)
    return {"ok": True}


@app.post("/api/drift")
def drift() -> dict:
    _require_llm()
    desk.check_drift()
    return {"ok": True}


@app.post("/api/reset")
def reset() -> dict:
    desk.reset()
    return {"ok": True}


@app.get("/api/events")
async def events(request: Request):
    async def stream():
        queue = desk.bus.subscribe()
        try:
            while True:
                if await request.is_disconnected():
                    break
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=15)
                except TimeoutError:
                    yield {"event": "ping", "data": "{}"}
                    continue
                yield {"event": "message", "data": json.dumps(event, default=str)}
        finally:
            desk.bus.unsubscribe(queue)

    return EventSourceResponse(stream())


@app.get("/api/history")
def history() -> list[dict]:
    return desk.bus.history[-500:]


_dist = ROOT / "web" / "dist"
if _dist.exists():
    app.mount("/assets", StaticFiles(directory=_dist / "assets"), name="assets")

    @app.get("/{path:path}")
    def spa(path: str):
        target = _dist / path
        if path and target.is_file():
            return FileResponse(target)
        return FileResponse(_dist / "index.html")

