export type Category = "context" | "decision" | "execution" | "trajectory";

export interface Step {
  id: string;
  kind: "tool" | "commit" | "verify" | "llm";
  name: string;
  args: Record<string, unknown>;
  result: unknown;
  ok: boolean;
  duration_ms: number;
}

export interface Finding {
  code: string;
  category: Category;
  route: "mechanical" | "choice";
  title: string;
  detail: string;
  evidence: string[];
  data: Record<string, unknown>;
  tier: "deterministic" | "judge";
}

export interface AttemptRecord {
  number: number;
  steps: Step[];
  staged: Record<string, unknown>[];
  draft: string;
  decision_request: { question: string; options: string[] } | null;
  findings: Finding[];
  post_commit?: Finding[];
  judge?: Finding[];
}

export interface Fix {
  attempt: number;
  code: string;
  category: Category;
  title: string;
  action: string;
  verified: boolean;
  verified_by?: string;
}

export interface Run {
  ticket_id: string;
  status: TicketStatus;
  trace_id: string | null;
  trace_url: string | null;
  attempts: AttemptRecord[];
  fixes: Fix[];
  commits: { action: Record<string, unknown>; result: Record<string, unknown>; ok: boolean; step_id: string }[];
  reply: string;
  applied_rule: string | null;
  error: string | null;
}

export type TicketStatus = "queued" | "pending" | "running" | "resolved" | "waiting_on_you" | "failed";

export interface Ticket {
  id: string;
  from: string;
  subject: string;
  body: string;
  status: TicketStatus;
  source: "seed" | "custom";
  latest: Run | null;
  runs: number;
}

export interface DriftResult {
  id: string;
  title: string;
  why: string;
  passed: boolean;
  detail: string;
  status: string;
  trace_url: string | null;
  fixes: number;
}

export interface Drift {
  passed: number;
  total: number;
  results: DriftResult[];
  at?: string;
  rule?: string | null;
}

export interface Rule {
  id: string;
  version: number;
  min_tenure_years: number;
  max_days_over: number;
  outcome: "refund" | "store_credit" | "decline";
  question: string;
  source_ticket: string;
  decided_by: string;
  status: "active" | "held" | "candidate";
  created_at: string;
  held_reason: string | null;
  describe: string;
}

export interface Decision {
  id: string;
  ticket_id: string;
  status: "open" | "checking" | "answering" | "answered" | "held";
  question: string;
  why: string;
  facts: {
    customer: string;
    plan: string;
    tenure_years: number;
    product: string;
    amount: number;
    days_since_purchase: number;
    window_days: number;
    days_over: number;
  };
  evidence: Step[];
  options: { value: Rule["outcome"]; label: string }[];
  suggested_scope: { min_tenure_years: number; max_days_over: number };
  trace_url: string | null;
  attempts: { rule: Rule; drift: Drift; at: string }[];
  scope?: "once" | "always";
  rule?: Rule;
}

export interface Stats {
  resolved: number;
  waiting: number;
  fixed_alone: number;
  fixed_verified: number;
  asked: number;
  rules: number;
  rule_reuses: number;
}

export interface DeskState {
  tickets: Ticket[];
  decisions: Decision[];
  policies: Rule[];
  index: string[];
  drift: Drift | null;
  stats: Stats;
  tracing: { exporting: boolean; dashboard: string; readback: boolean };
  busy: boolean;
  llm_ready: boolean;
  today: string;
}

export interface DeskEvent {
  id: number;
  type: string;
  ts: number;
  ticket_id?: string;
  [key: string]: unknown;
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { DeskEvent, DeskState } from "./types";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
  });
  if (!response.ok) {
    let message = `${response.status} ${response.statusText}`;
    try {
      const body = await response.json();
      if (body?.detail) message = typeof body.detail === "string" ? body.detail : JSON.stringify(body.detail);
    } catch {
      /* keep status text */
    }
    throw new Error(message);
  }
  return response.json() as Promise<T>;
}

export const api = {
  state: () => request<DeskState>("/api/state"),
  history: () => request<DeskEvent[]>("/api/history"),
  runQueue: () => request("/api/run", { method: "POST" }),
  runTicket: (id: string) => request(`/api/tickets/${id}/run`, { method: "POST" }),
  addTicket: (sender: string, subject: string, body: string) =>
    request<{ id: string }>("/api/tickets", { method: "POST", body: JSON.stringify({ sender, subject, body }) }),
  answer: (id: string, body: { outcome: string; scope: string; min_tenure_years: number; max_days_over: number }) =>
    request(`/api/decisions/${id}`, { method: "POST", body: JSON.stringify(body) }),
  drift: () => request("/api/drift", { method: "POST" }),
  reset: () => request("/api/reset", { method: "POST" }),
};

/** Desk state, refreshed whenever the server emits an event. */
export function useDesk() {
  const [state, setState] = useState<DeskState | null>(null);
  const [events, setEvents] = useState<DeskEvent[]>([]);
  const [connected, setConnected] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const timer = useRef<number | null>(null);

  const refresh = useCallback(async () => {
    try {
      setState(await api.state());
      setError(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, []);

  const scheduleRefresh = useCallback(() => {
    if (timer.current) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(refresh, 150);
  }, [refresh]);

  useEffect(() => {
    refresh();
    api.history().then(setEvents).catch(() => undefined);
    const source = new EventSource("/api/events");
    source.onopen = () => setConnected(true);
    source.onerror = () => setConnected(false);
    source.onmessage = (message) => {
      const event = JSON.parse(message.data) as DeskEvent;
      if (event.type === "desk.reset") setEvents([]);
      else setEvents((prev) => [...prev.slice(-400), event]);
      scheduleRefresh();
    };
    return () => source.close();
  }, [refresh, scheduleRefresh]);

  return { state, events, connected, error, refresh };
}

import type { ReactNode } from "react";
import type { Category, TicketStatus } from "../types";

export function cx(...parts: (string | false | null | undefined)[]) {
  return parts.filter(Boolean).join(" ");
}

export function Panel({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <section
      className={cx(
        "rounded-2xl border border-border bg-card/65 shadow-2xl shadow-black/20 backdrop-blur-xl",
        className,
      )}
    >
      {children}
    </section>
  );
}

export function HudLabel({ icon, children, right }: { icon?: ReactNode; children: ReactNode; right?: ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-3">
      <div className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.18em] text-muted-foreground">
        {icon && <span className="text-primary [&>svg]:size-3.5">{icon}</span>}
        {children}
      </div>
      {right}
    </div>
  );
}

const STATUS: Record<TicketStatus, { label: string; dot: string; text: string; pulse?: boolean }> = {
  queued: { label: "Queued", dot: "bg-muted-foreground/50", text: "text-muted-foreground" },
  pending: { label: "Up next", dot: "bg-info", text: "text-info" },
  running: { label: "Working", dot: "bg-primary", text: "text-primary", pulse: true },
  resolved: { label: "Resolved", dot: "bg-primary", text: "text-foreground" },
  waiting_on_you: { label: "Needs you", dot: "bg-warn", text: "text-warn", pulse: true },
  failed: { label: "Failed", dot: "bg-danger", text: "text-danger" },
};

export function Dot({ className, pulse }: { className: string; pulse?: boolean }) {
  return (
    <span className="relative flex size-1.5 shrink-0">
      {pulse && <span className={cx("absolute inline-flex size-full animate-ping rounded-full opacity-60", className)} />}
      <span className={cx("relative inline-flex size-1.5 rounded-full", className)} />
    </span>
  );
}

export function StatusTag({ status }: { status: TicketStatus }) {
  const s = STATUS[status];
  return (
    <span className={cx("inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[0.14em]", s.text)}>
      <Dot className={s.dot} pulse={s.pulse} />
      {s.label}
    </span>
  );
}

const CATEGORY: Record<Category, string> = {
  context: "text-info border-info/30 bg-info/10",
  decision: "text-warn border-warn/30 bg-warn/10",
  execution: "text-danger border-danger/30 bg-danger/10",
  trajectory: "text-agent border-agent/30 bg-agent/10",
};

export function CategoryTag({ category }: { category: Category }) {
  return (
    <span
      className={cx(
        "rounded-md border px-1.5 py-0.5 font-mono text-[9px] uppercase tracking-[0.14em]",
        CATEGORY[category],
      )}
    >
      {category}
    </span>
  );
}

export function Button({
  children,
  onClick,
  variant = "secondary",
  disabled,
  className,
  type = "button",
  title,
}: {
  children: ReactNode;
  onClick?: () => void;
  variant?: "primary" | "secondary" | "ghost";
  disabled?: boolean;
  className?: string;
  type?: "button" | "submit";
  title?: string;
}) {
  const styles = {
    primary:
      "bg-primary text-primary-foreground shadow-[0_0_20px_rgba(200,245,106,0.2)] hover:-translate-y-0.5 hover:shadow-[0_0_32px_rgba(200,245,106,0.35)]",
    secondary: "border border-border text-foreground hover:bg-muted/60",
    ghost: "text-muted-foreground hover:text-foreground hover:bg-muted/40",
  }[variant];
  return (
    <button
      type={type}
      title={title}
      onClick={onClick}
      disabled={disabled}
      className={cx(
        "inline-flex items-center justify-center gap-2 rounded-full px-4 py-2 text-sm font-medium transition-all duration-200 active:translate-y-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/70 disabled:pointer-events-none disabled:opacity-40",
        styles,
        className,
      )}
    >
      {children}
    </button>
  );
}

export function Empty({ icon, title, children }: { icon: ReactNode; title: string; children?: ReactNode }) {
  return (
    <div className="flex flex-col items-center justify-center gap-3 px-6 py-12 text-center">
      <span className="flex size-10 items-center justify-center rounded-xl border border-border bg-muted/40 text-muted-foreground [&>svg]:size-4">
