}

export function money(n: number) {
  return `$${n.toFixed(2)}`;
}

import { motion } from "motion/react";
import { Inbox, Repeat2, Sparkles, Wrench } from "lucide-react";
import type { Ticket } from "../types";
import { HudLabel, Panel, StatusTag, cx } from "./ui";

export function Queue({
  tickets,
  selected,
  onSelect,
}: {
  tickets: Ticket[];
  selected: string | null;
  onSelect: (id: string) => void;
}) {
  return (
    <Panel className="flex min-h-0 flex-col">
      <div className="border-b border-border px-4 py-3.5">
        <HudLabel icon={<Inbox />} right={<span className="font-mono text-[10px] text-muted-foreground">{tickets.length}</span>}>
          Ticket queue
        </HudLabel>
      </div>
      <ul className="scrollbar-thin min-h-0 flex-1 overflow-y-auto p-2">
        {tickets.map((t, i) => {
          const fixes = t.latest?.fixes.length ?? 0;
          return (
            <motion.li
              key={t.id}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.03, duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
            >
              <button
                onClick={() => onSelect(t.id)}
                className={cx(
                  "group w-full rounded-xl border px-3 py-2.5 text-left transition-colors duration-150 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
                  selected === t.id
                    ? "border-primary/30 bg-primary/[0.06]"
                    : "border-transparent hover:border-border hover:bg-muted/40",
                )}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="font-mono text-[10px] text-muted-foreground">{t.id}</span>
                  <StatusTag status={t.status} />
                </div>
                <p className="mt-1 truncate text-sm font-medium">{t.subject}</p>
                <p className="truncate text-xs text-muted-foreground">{t.from}</p>
                {(fixes > 0 || t.latest?.applied_rule || t.source === "custom") && (
                  <div className="mt-1.5 flex flex-wrap gap-1.5">
                    {fixes > 0 && (
                      <span className="inline-flex items-center gap-1 font-mono text-[9px] uppercase tracking-[0.12em] text-primary">
                        <Wrench className="size-3" /> fixed {fixes}
                      </span>
                    )}
                    {t.latest?.applied_rule && (
                      <span className="inline-flex items-center gap-1 font-mono text-[9px] uppercase tracking-[0.12em] text-warn">
                        <Repeat2 className="size-3" /> your rule
                      </span>
                    )}
                    {t.source === "custom" && (
                      <span className="inline-flex items-center gap-1 font-mono text-[9px] uppercase tracking-[0.12em] text-info">
                        <Sparkles className="size-3" /> your ticket
                      </span>
                    )}
                  </div>
                )}
              </button>
            </motion.li>
          );
        })}
      </ul>
    </Panel>
  );
}

import { AnimatePresence, motion } from "motion/react";
import {
  ArrowUpRight,
  Ban,
  Check,
  ChevronDown,
  CircleAlert,
  FlaskConical,
  Hand,
  Mail,
  Play,
  Repeat2,
  ShieldCheck,
  Wrench,
} from "lucide-react";
import { useState } from "react";
import type { AttemptRecord, DeskEvent, Finding, Fix, Run, Step, Ticket } from "../types";
import { Button, CategoryTag, Dot, Empty, HudLabel, Panel, StatusTag, cx } from "./ui";

function short(value: unknown, max = 70): string {
  const text = typeof value === "string" ? value : JSON.stringify(value);
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

function StepRow({ step }: { step: Step }) {
  const [open, setOpen] = useState(false);
  const kindColor = {
    tool: "text-info",
    commit: "text-warn",
    verify: "text-primary",
    llm: "text-agent",
  }[step.kind];
  const args = Object.values(step.args).filter((v) => typeof v === "string" || typeof v === "number");
  return (
    <li>
      <button
        onClick={() => setOpen((o) => !o)}
        className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left font-mono text-[12px] transition-colors hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring/60"
      >
        <span className="w-9 shrink-0 text-[10px] text-muted-foreground/70">{step.id.split(".")[1]}</span>
        <span className={cx("shrink-0", kindColor)}>{step.name}</span>
        <span className="min-w-0 flex-1 truncate text-muted-foreground">{args.map((a) => short(a, 40)).join(" · ")}</span>
        {step.ok ? (
          <Check className="size-3.5 shrink-0 text-primary/80" />
        ) : (
          <CircleAlert className="size-3.5 shrink-0 text-danger" />
        )}
        <ChevronDown className={cx("size-3 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")} />
      </button>
      <AnimatePresence initial={false}>
        {open && (
          <motion.pre
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="scrollbar-thin mx-2 mb-1 max-h-56 overflow-auto rounded-lg border border-border bg-[#09090b] p-3 font-mono text-[11px] leading-relaxed text-muted-foreground"
          >
            {JSON.stringify({ args: step.args, result: step.result }, null, 2)}
          </motion.pre>
        )}
      </AnimatePresence>
    </li>
  );
}

function FindingCard({ finding, fix }: { finding: Finding; fix?: Fix }) {
  const isChoice = finding.route === "choice";
  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 6 }}
      animate={{ opacity: 1, y: 0 }}
      className={cx(
        "rounded-xl border p-3.5",
        isChoice ? "border-warn/30 bg-warn/[0.06]" : "border-danger/25 bg-danger/[0.05]",
      )}
    >
      <div className="flex flex-wrap items-center gap-2">
        <CategoryTag category={finding.category} />
        {finding.tier === "judge" && (
          <span className="font-mono text-[9px] uppercase tracking-[0.14em] text-agent">tier-2 judge</span>
        )}
        <span className="text-sm font-medium">{finding.title}</span>
      </div>
      <p className="mt-1.5 text-[13px] leading-relaxed text-muted-foreground">{finding.detail}</p>
      {typeof finding.data.fault_label === "string" && (
        <p className="mt-2 inline-flex items-center gap-1.5 rounded-md border border-border bg-muted/40 px-2 py-1 font-mono text-[10px] text-muted-foreground">
          <FlaskConical className="size-3" /> {finding.data.fault_label}
        </p>
      )}
      <div className="mt-2.5 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.14em]">
        {isChoice ? (
          <span className="inline-flex items-center gap-1.5 text-warn">
            <Hand className="size-3" /> A choice: sent to you
          </span>
        ) : fix ? (
          <span className="inline-flex items-center gap-1.5 text-primary">
            <Wrench className="size-3" /> Mechanical: fixed by Once
          </span>
        ) : (
          <span className="text-muted-foreground">Mechanical</span>
        )}
      </div>
      {fix && (
        <div className="mt-2 flex items-start gap-2 border-t border-border pt-2 text-[13px]">
          <span className="text-foreground/90">{fix.action}</span>
        </div>
      )}
    </motion.div>
  );
}

function AttemptBlock({ attempt, fixes, last }: { attempt: AttemptRecord; fixes: Fix[]; last: boolean }) {
  const [showDraft, setShowDraft] = useState(attempt.findings.length > 0);
  const findings = [...attempt.findings, ...(attempt.post_commit ?? []), ...(attempt.judge ?? [])];
  const clean = findings.length === 0;
  return (
    <div className="relative pl-6">
      <span
        className={cx(
          "absolute left-0 top-1 flex size-3.5 items-center justify-center rounded-full border",
          clean ? "border-primary/50 bg-primary/20" : "border-danger/50 bg-danger/20",
        )}
      />
      {!last && <span className="absolute bottom-[-12px] left-[6.5px] top-5 w-px bg-border" />}
      <div className="flex items-center justify-between gap-3">
        <span className="font-mono text-[11px] uppercase tracking-[0.16em] text-muted-foreground">
          Attempt {attempt.number}
        </span>
        <span className={cx("font-mono text-[10px] uppercase tracking-[0.14em]", clean ? "text-primary" : "text-danger")}>
          {clean ? "passed checks" : `${findings.length} finding${findings.length > 1 ? "s" : ""}`}
        </span>
      </div>
      <ul className="mt-2 rounded-xl border border-border bg-black/20 p-1">
        {attempt.steps.map((s) => (
          <StepRow key={s.id} step={s} />
        ))}
        {attempt.steps.length === 0 && <li className="px-2 py-1.5 font-mono text-[12px] text-muted-foreground">no tool calls</li>}
      </ul>
      {attempt.draft && (
        <div className="mt-2">
          <button
            onClick={() => setShowDraft((s) => !s)}
            className="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground hover:text-foreground"
          >
            <ChevronDown className={cx("size-3 transition-transform", showDraft && "rotate-180")} />
            Agent's draft {!clean && "(blocked)"}
          </button>
          {showDraft && (
            <p
              className={cx(
                "mt-1.5 whitespace-pre-wrap rounded-xl border px-3.5 py-3 text-[13px] leading-relaxed",
                clean ? "border-border text-foreground/80" : "border-danger/20 text-muted-foreground line-through decoration-danger/40",
              )}
            >
              {attempt.draft}
            </p>
          )}
        </div>
      )}
      {findings.length > 0 && (
        <div className="mt-3 space-y-2">
          {findings.map((f, i) => (
            <FindingCard key={`${f.code}-${i}`} finding={f} fix={fixes.find((x) => x.code === f.code)} />
          ))}
        </div>
      )}
    </div>
  );
}

function LiveLine({ events }: { events: DeskEvent[] }) {
  const last = events[events.length - 1];
  const label: Record<string, string> = {
    "ticket.started": "Reading the ticket",
    "attempt.started": `Agent working (attempt ${last?.attempt ?? ""})`,
    "attempt.checked": "Checking claims against tool results",
    "fix.applied": "Applying a fix",
    "fix.verified": "Verifying the fix",
    "attempt.post_checked": "Reading side effects back",
  };
  return (
    <div className="flex items-center gap-2 rounded-xl border border-primary/30 bg-primary/[0.06] px-3.5 py-2.5 font-mono text-[11px] uppercase tracking-[0.14em] text-primary">
      <Dot className="bg-primary" pulse />
      {label[last?.type] ?? "Working"}
    </div>
  );
}

export function TicketDetail({
  ticket,
  events,
  canRun,
  onRun,
  onJumpToDecision,
}: {
  ticket: Ticket | null;
  events: DeskEvent[];
  canRun: boolean;
  onRun: (id: string) => void;
  onJumpToDecision: () => void;
}) {
  if (!ticket) {
    return (
      <Panel className="flex items-center justify-center">
        <Empty icon={<Mail />} title="Pick a ticket">
          Select a ticket from the queue to watch the loop: act, check, fix or ask, verify.
        </Empty>
      </Panel>
    );
  }
  const run: Run | null = ticket.latest;
  const live = events.filter((e) => e.ticket_id === ticket.id);
  const running = ticket.status === "running" || ticket.status === "pending";
  return (
    <Panel className="flex min-h-0 flex-col">
      <div className="border-b border-border px-5 py-3.5">
        <HudLabel
          icon={<Play />}
          right={
            <div className="flex items-center gap-3">
              {run?.trace_id && (
                <a
                  href={run.trace_url ?? undefined}
                  target="_blank"
                  rel="noreferrer"
                  title={run.trace_url ? "Open in neatlogs" : "Trace export is off: set NEATLOGS_API_KEY"}
                  className={cx(
                    "inline-flex items-center gap-1 font-mono text-[10px]",
                    run.trace_url ? "text-primary hover:underline" : "pointer-events-none text-muted-foreground",
                  )}
                >
                  trace {run.trace_id.slice(0, 8)} {run.trace_url && <ArrowUpRight className="size-3" />}
                </a>
              )}
              <StatusTag status={ticket.status} />
            </div>
          }
        >
          The loop · {ticket.id}
        </HudLabel>
      </div>

      <div className="scrollbar-thin min-h-0 flex-1 space-y-5 overflow-y-auto px-5 py-5">
        <div>
          <p className="text-lg font-semibold tracking-[-0.02em]">{ticket.subject}</p>
          <p className="mt-0.5 font-mono text-[11px] text-muted-foreground">{ticket.from}</p>
          <p className="mt-3 rounded-xl border border-border bg-muted/30 px-4 py-3 text-[14px] leading-relaxed text-foreground/85">
            {ticket.body}
          </p>
        </div>

        {running && <LiveLine events={live} />}

        {!run && !running && (
          <div className="flex flex-col items-start gap-3 rounded-xl border border-dashed border-border px-4 py-5">
            <p className="text-sm text-muted-foreground">Not run yet.</p>
            <Button variant="secondary" onClick={() => onRun(ticket.id)} disabled={!canRun}>
              <Play className="size-3.5" /> Run this ticket
            </Button>
          </div>
        )}

        {run && (
          <div className="space-y-5">
            {run.attempts.map((a, i) => (
              <AttemptBlock
                key={`${run.trace_id}-${a.number}`}
                attempt={a}
                fixes={run.fixes.filter((f) => f.attempt === a.number)}
                last={i === run.attempts.length - 1}
              />
            ))}
          </div>
        )}

        {run?.status === "waiting_on_you" && (
          <button
            onClick={onJumpToDecision}
            className="flex w-full items-center justify-between rounded-xl border border-warn/40 bg-warn/[0.08] px-4 py-3 text-left transition-colors hover:bg-warn/[0.12]"
          >
            <span className="flex items-center gap-2 text-sm font-medium text-warn">
              <Hand className="size-4" /> This one is a business decision. Once is waiting on you.
            </span>
            <ArrowUpRight className="size-4 text-warn" />
          </button>
        )}

        {run?.status === "failed" && (
          <div className="flex items-start gap-2 rounded-xl border border-danger/40 bg-danger/[0.08] px-4 py-3 text-sm text-danger">
            <Ban className="mt-0.5 size-4 shrink-0" /> {run.error}
          </div>
        )}

        {run?.status === "resolved" && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="rounded-xl border border-primary/30 bg-primary/[0.05] p-4"
          >
            <div className="flex flex-wrap items-center justify-between gap-2">
              <span className="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[0.16em] text-primary">
                <ShieldCheck className="size-3.5" /> Sent to customer
              </span>
              <div className="flex flex-wrap gap-3 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">
                {run.fixes.length > 0 && (
                  <span>
                    {run.fixes.filter((f) => f.verified).length}/{run.fixes.length} fixes verified
                  </span>
                )}
                {run.applied_rule && (
                  <span className="inline-flex items-center gap-1 text-warn">
                    <Repeat2 className="size-3" /> applied your rule
                  </span>
                )}
              </div>
            </div>
            <p className="mt-3 whitespace-pre-wrap text-[14px] leading-relaxed">{run.reply}</p>
            {run.commits.length > 0 && (
              <div className="mt-3 flex flex-wrap gap-2 border-t border-border pt-3">
                {run.commits.map((c) => (
                  <span key={c.step_id} className="rounded-md border border-border bg-muted/40 px-2 py-1 font-mono text-[10px] text-muted-foreground">
                    {String(c.action.type)} · {String(c.action.order_id)}
                    {typeof c.action.amount === "number" && ` · $${c.action.amount.toFixed(2)}`}
                  </span>
                ))}
              </div>
            )}
          </motion.div>
        )}
      </div>
    </Panel>
  );
}

import { motion } from "motion/react";
import { Check, ChevronDown, Hand, Loader2, ShieldAlert, X } from "lucide-react";
import { useEffect, useState } from "react";
import { api } from "../api";
import type { Decision, Rule } from "../types";
import { Button, Dot, cx, money } from "./ui";

export function DecisionCard({ decision, onError }: { decision: Decision; onError: (m: string) => void }) {
  const [outcome, setOutcome] = useState<Rule["outcome"] | null>(null);
  const [scope, setScope] = useState<"always" | "once">("always");
  const [tenure, setTenure] = useState(decision.suggested_scope.min_tenure_years);
  const [days, setDays] = useState(decision.suggested_scope.max_days_over);
  const [showEvidence, setShowEvidence] = useState(false);
  const [sending, setSending] = useState(false);
  const busy = decision.status === "checking" || decision.status === "answering" || sending;
  const lastAttempt = decision.attempts[decision.attempts.length - 1];
  const f = decision.facts;

  useEffect(() => {
    if (decision.status !== "open" && decision.status !== "held") setSending(false);
  }, [decision.status]);

  async function submit() {
    if (!outcome) return;
    setSending(true);
    try {
      await api.answer(decision.id, { outcome, scope, min_tenure_years: tenure, max_days_over: days });
    } catch (e) {
      setSending(false);
      onError(e instanceof Error ? e.message : String(e));
    }
  }

  if (decision.status === "answered") {
    return (
      <div className="rounded-xl border border-border bg-muted/20 p-3.5">
        <div className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.14em] text-primary">
          <Check className="size-3.5" /> Answered · {decision.ticket_id}
        </div>
        <p className="mt-1.5 text-[13px] leading-relaxed text-muted-foreground">
          {decision.scope === "always" && decision.rule
            ? `Saved as rule v${decision.rule.version}. Once won't ask this again.`
            : "Applied to this ticket only."}
        </p>
      </div>
    );
  }

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 16, scale: 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ duration: 0.35, ease: [0.16, 1, 0.3, 1] }}
      className="rounded-2xl border border-warn/35 bg-warn/[0.05] p-4 shadow-[0_0_40px_rgba(240,190,80,0.06)]"
    >
      <div className="flex items-center justify-between gap-2">
        <span className="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[0.16em] text-warn">
          <Hand className="size-3.5" /> Your call · {decision.ticket_id}
        </span>
        <span className="font-mono text-[10px] text-muted-foreground">asked once</span>
      </div>

      <p className="mt-3 text-[15px] font-medium leading-snug">{decision.question}</p>

      <dl className="mt-3 grid grid-cols-3 gap-2">
        {[
          ["Customer for", `${f.tenure_years} yrs`],
          ["Past window", `${f.days_over} day${f.days_over === 1 ? "" : "s"}`],
          ["Order", money(f.amount)],
        ].map(([k, v]) => (
          <div key={k} className="rounded-lg border border-border bg-black/20 px-2.5 py-2">
            <dt className="font-mono text-[9px] uppercase tracking-[0.14em] text-muted-foreground">{k}</dt>
            <dd className="mt-0.5 text-sm font-semibold">{v}</dd>
          </div>
        ))}
      </dl>

      <button
        onClick={() => setShowEvidence((s) => !s)}
        className="mt-3 inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground hover:text-foreground"
      >
        <ChevronDown className={cx("size-3 transition-transform", showEvidence && "rotate-180")} />
        What the agent found ({decision.evidence.length} steps)
      </button>
      {showEvidence && (
        <div className="mt-2 space-y-1.5">
          <p className="text-[13px] leading-relaxed text-muted-foreground">{decision.why}</p>
          {decision.evidence.map((s) => (
            <pre
              key={s.id}
              className="scrollbar-thin max-h-28 overflow-auto rounded-lg border border-border bg-[#09090b] p-2 font-mono text-[10.5px] leading-relaxed text-muted-foreground"
            >
              {s.name}({JSON.stringify(s.args)}) → {JSON.stringify(s.result)}
            </pre>
          ))}
        </div>
      )}

      {decision.status === "held" && lastAttempt && (
        <div className="mt-3 rounded-xl border border-danger/35 bg-danger/[0.07] p-3">
          <p className="inline-flex items-center gap-1.5 text-sm font-medium text-danger">
            <ShieldAlert className="size-4" /> Rule held: it would break {lastAttempt.drift.total - lastAttempt.drift.passed} of
            ACME's distinctive cases
          </p>
          <ul className="mt-2 space-y-1">
            {lastAttempt.drift.results
              .filter((r) => !r.passed)
              .map((r) => (
                <li key={r.id} className="flex gap-2 text-[12.5px] leading-snug text-muted-foreground">
                  <X className="mt-0.5 size-3.5 shrink-0 text-danger" />
                  <span>
                    <span className="text-foreground">{r.title}.</span> {r.detail}
                  </span>
                </li>
              ))}
          </ul>
          <p className="mt-2 text-[12.5px] text-muted-foreground">Narrow the rule and try again.</p>
        </div>
      )}

      {busy ? (
        <div className="mt-4 flex items-center gap-2 rounded-xl border border-primary/30 bg-primary/[0.06] px-3.5 py-3 font-mono text-[11px] uppercase tracking-[0.14em] text-primary">
          {decision.status === "checking" ? (
            <>
              <Dot className="bg-primary" pulse /> Replaying distinctive cases before saving the rule
            </>
          ) : (
            <>
              <Loader2 className="size-3.5 animate-spin" /> Applying your answer
            </>
          )}
        </div>
      ) : (
        <>
          <div className="mt-4 grid gap-1.5">
            {decision.options.map((o) => (
              <button
                key={o.value}
                onClick={() => setOutcome(o.value)}
                className={cx(
                  "flex items-center justify-between rounded-xl border px-3.5 py-2.5 text-left text-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
                  outcome === o.value
                    ? "border-primary/50 bg-primary/[0.1] text-foreground"
                    : "border-border hover:bg-muted/50",
                )}
              >
                {o.label}
                {outcome === o.value && <Check className="size-4 text-primary" />}
              </button>
            ))}
          </div>

          <div className="mt-3 inline-flex rounded-full border border-border p-0.5">
            {(["always", "once"] as const).map((s) => (
              <button
                key={s}
                onClick={() => setScope(s)}
                className={cx(
                  "rounded-full px-3 py-1 text-xs font-medium transition-colors",
                  scope === s ? "bg-foreground text-background" : "text-muted-foreground hover:text-foreground",
                )}
              >
                {s === "always" ? "Make it a rule" : "Just this ticket"}
              </button>
            ))}
          </div>

          {scope === "always" && (
            <div className="mt-3 rounded-xl border border-border bg-black/20 p-3 text-[13px] leading-relaxed text-muted-foreground">
              Apply to customers of{" "}
              <input
                type="number"
                min={0}
                step={0.5}
                value={tenure}
                onChange={(e) => setTenure(Number(e.target.value))}
                aria-label="Minimum years as a customer"
                className="w-14 rounded-md border border-border bg-muted/50 px-1.5 py-0.5 text-center font-mono text-foreground focus:border-primary/60 focus:outline-none"
              />{" "}
              + years, up to{" "}
              <input
                type="number"
                min={1}
                value={days}
                onChange={(e) => setDays(Number(e.target.value))}
                aria-label="Maximum days past the window"
                className="w-14 rounded-md border border-border bg-muted/50 px-1.5 py-0.5 text-center font-mono text-foreground focus:border-primary/60 focus:outline-none"
              />{" "}
              days past the window. Once replays ACME's distinctive cases before saving it.
            </div>
          )}

          <Button variant="primary" className="mt-4 w-full" disabled={!outcome} onClick={submit}>
            {scope === "always" ? "Decide and remember" : "Decide for this ticket"}
          </Button>
        </>
      )}
    </motion.div>
  );
}

