  --color-subtle: #fbfbfa;
  --color-line: #eaeaea;
  --color-ink: #2f3437;
  --color-ink-strong: #111111;
  --color-muted: #787774;
  --color-faint: #a5a49f;

  --color-red-bg: #fdebec;
  --color-red-fg: #9f2f2d;
  --color-blue-bg: #e1f3fe;
  --color-blue-fg: #1f6c9f;
  --color-green-bg: #edf3ec;
  --color-green-fg: #346538;
  --color-yellow-bg: #fbf3db;
